package com.bank.codec;

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.logging.Logger;

// Serializes/deserializes a hierarchy via preorder with null markers.
public class TreeCodecService {

    private static final Logger log = Logger.getLogger(TreeCodecService.class.getName());

    private static final String NULL = "#";
    private static final String DELIM = ",";

    public String serialize(RoleNode root) {
        StringBuilder sb = new StringBuilder();
        buildString(root, sb);
        String out = sb.toString();
        log.info(() -> "Serialized hierarchy: " + out);
        return out;
    }

    private void buildString(RoleNode node, StringBuilder sb) {
        if (node == null) {
            sb.append(NULL).append(DELIM);   // explicit null marker
            return;
        }
        sb.append(node.getRole()).append(DELIM); // node value
        buildString(node.getLeft(), sb);         // then left
        buildString(node.getRight(), sb);        // then right
    }

    public RoleNode deserialize(String data) {
        Deque<String> tokens = new ArrayDeque<>();
        for (String t : data.split(DELIM)) {
            tokens.offer(t);
        }
        RoleNode root = buildTree(tokens);
        log.info("Deserialized hierarchy back into a tree");
        return root;
    }

    private RoleNode buildTree(Deque<String> tokens) {
        String token = tokens.poll();
        if (NULL.equals(token)) {
            return null;                          // branch ends here
        }
        RoleNode node = new RoleNode(token);
        node.setLeft(buildTree(tokens));          // same preorder order
        node.setRight(buildTree(tokens));
        return node;
    }

    public String preorderString(RoleNode node) {
        if (node == null) return "_";
        return node.getRole() + "(" + preorderString(node.getLeft())
                + "," + preorderString(node.getRight()) + ")";
    }
}
