package com.bank.codec;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class CodecDemo {

    private static final Logger log = Logger.getLogger(CodecDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) {
            root.removeHandler(h);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Hierarchy Serialize/Deserialize");

        //  Manager
        //   /    \
        // Credit  Risk
        //           \
        //         Regional
        RoleNode manager = new RoleNode("Manager");
        manager.setLeft(new RoleNode("Credit"));
        manager.setRight(new RoleNode("Risk"));
        manager.getRight().setRight(new RoleNode("Regional"));

        TreeCodecService service = new TreeCodecService();
        String data = service.serialize(manager);
        RoleNode rebuilt = service.deserialize(data);
        log.info("Round-trip check: " + service.preorderString(rebuilt));
    }
}
